<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
require_once dirname(__DIR__) . '/classes/IdiomaService.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
// Textos em Administração › Textos e idiomas (cadastro automático ao abrir como ADMINISTRADOR).
$tt = static fn(string $chave, array $padrao): string => htmlspecialchars(IdiomaService::t($chave, $padrao), ENT_QUOTES, 'UTF-8');
$sessaoExpirada = IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.']);
if (empty($_SESSION['autenticado'])) { http_response_code(401); exit($sessaoExpirada); }
$env = [];
foreach (file(dirname(__DIR__) . DIRECTORY_SEPARATOR . '.env', FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) { $line = trim($line); if ($line === '' || $line[0] === '#' || !str_contains($line, '=')) continue; [$key, $value] = explode('=', $line, 2); $env[trim($key)] = trim(trim($value), "\"'"); }
$tenant = (string)($_SESSION['tenant']['banco_dados'] ?? '');
$tenantPdo = new PDO('mysql:host=' . ($env['GPT_DB_HOST'] ?? '127.0.0.1') . ';port=' . ($env['GPT_DB_PORT'] ?? '3306') . ';dbname=' . $tenant . ';charset=utf8mb4', $env['GPT_DB_USERNAME'] ?? '', $env['GPT_DB_PASSWORD'] ?? '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
if (!UsuarioSessao::atualizar($tenantPdo, $_SESSION)) { http_response_code(401); exit($sessaoExpirada); }
$tenantPdo = TransactionSecurity::connect('REQUISITOS_LEGAIS');
$permission = PermissaoTransacao::obter('REQUISITOS_LEGAIS');
if (empty($permission['pode_visualizar'])) { http_response_code(403); exit(IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.sem_permissao', ['pt' => 'Seu perfil não tem permissão para acessar esta transação.', 'en' => 'Your profile is not allowed to access this transaction.', 'es' => 'Su perfil no tiene permiso para acceder a esta transacción.'])); }
$pdo = new PDO('mysql:host=' . ($env['GLEGISLACAO_DB_HOST'] ?? '127.0.0.1') . ';port=' . ($env['GLEGISLACAO_DB_PORT'] ?? '3306') . ';dbname=' . ($env['GLEGISLACAO_DB_DATABASE'] ?? 'glegislacao_dbp') . ';charset=utf8mb4', $env['GLEGISLACAO_DB_USERNAME'] ?? '', $env['GLEGISLACAO_DB_PASSWORD'] ?? '', [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
$lawId = (int)($_GET['CODLEGISLACAO'] ?? $_POST['CODLEGISLACAO'] ?? 0); if ($lawId < 1) { http_response_code(400); exit(IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.legislacao_invalida', ['pt' => 'Código da legislação inválido.', 'en' => 'Invalid legislation code.', 'es' => 'Código de legislación inválido.'])); }
$pageSize = 25;
$queryPage = static function (PDO $db, int $law, string $search, int $page, int $size): array {
    $where = 'WHERE x.CODLEGISLACAO = :law'; $params = [':law' => $law];
    if ($search !== '') { $where .= ' AND (CAST(p.CODPERGUNTA AS CHAR) LIKE :searchCode OR p.DSCPERGUNTA LIKE :searchText)'; $params[':searchCode'] = '%' . $search . '%'; $params[':searchText'] = '%' . $search . '%'; }
    $count = $db->prepare('SELECT COUNT(*) FROM perguntas p INNER JOIN legislacaoxpergunta x ON x.CODPERGUNTA = p.CODPERGUNTA ' . $where); $count->execute($params); $totalAssociated = (int)$count->fetchColumn();
    $whereAll = 'WHERE 1=1'; $allParams = [];
    if ($search !== '') { $whereAll .= ' AND (CAST(p.CODPERGUNTA AS CHAR) LIKE :searchCodeAll OR p.DSCPERGUNTA LIKE :searchTextAll)'; $allParams[':searchCodeAll'] = '%' . $search . '%'; $allParams[':searchTextAll'] = '%' . $search . '%'; }
    $countAll = $db->prepare('SELECT COUNT(*) FROM perguntas p ' . $whereAll); $countAll->execute($allParams); $total = (int)$countAll->fetchColumn();
    $sql = 'SELECT p.CODPERGUNTA, p.DSCPERGUNTA, CASE WHEN x.CODPERGUNTA IS NULL THEN 0 ELSE 1 END AS associado FROM perguntas p LEFT JOIN legislacaoxpergunta x ON x.CODLEGISLACAO = :lawList AND x.CODPERGUNTA = p.CODPERGUNTA ' . $whereAll . ' ORDER BY associado DESC, p.CODPERGUNTA LIMIT :limit OFFSET :offset';
    $paramsList = [':lawList' => $law] + $allParams; $statement = $db->prepare($sql); foreach ($paramsList as $key => $value) $statement->bindValue($key, $value); $statement->bindValue(':limit', $size, PDO::PARAM_INT); $statement->bindValue(':offset', ($page - 1) * $size, PDO::PARAM_INT); $statement->execute();
    return ['items' => $statement->fetchAll(PDO::FETCH_ASSOC), 'total' => $total, 'total_associadas' => $totalAssociated, 'pagina' => $page, 'paginas' => max(1, (int)ceil($total / $size))];
};
if (($_POST['action'] ?? '') === 'load_checklist') {
    $search = trim((string)($_POST['busca'] ?? '')); $page = max(1, (int)($_POST['pagina'] ?? 1)); $data = $queryPage($pdo, $lawId, $search, $page, $pageSize); header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => true] + $data, JSON_UNESCAPED_UNICODE); exit;
}
if (($_POST['action'] ?? '') === 'save_checklist') {
    if (empty($permission['pode_incluir']) && empty($permission['pode_excluir'])) { http_response_code(403); exit(json_encode(['ok' => false, 'message' => IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.sem_permissao_alterar', ['pt' => 'Seu perfil não tem permissão para alterar o checklist.', 'en' => 'Your profile is not allowed to change the checklist.', 'es' => 'Su perfil no tiene permiso para modificar el checklist.'])], JSON_UNESCAPED_UNICODE)); }
    $selected = json_decode((string)($_POST['perguntas'] ?? '[]'), true); $selected = array_values(array_unique(array_filter(array_map('intval', is_array($selected) ? $selected : []))));
    $currentStatement = $pdo->prepare('SELECT CODPERGUNTA FROM legislacaoxpergunta WHERE CODLEGISLACAO = :law'); $currentStatement->execute([':law' => $lawId]); $current = array_map('intval', $currentStatement->fetchAll(PDO::FETCH_COLUMN)); $currentMap = array_fill_keys($current, true);
    $removed = array_values(array_diff($current, $selected)); $added = array_values(array_diff($selected, $current));
    if ($added && empty($permission['pode_incluir'])) { http_response_code(403); exit(json_encode(['ok' => false, 'message' => IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.sem_permissao_incluir', ['pt' => 'Sem permissão para incluir perguntas.', 'en' => 'Not allowed to add questions.', 'es' => 'Sin permiso para incluir preguntas.'])], JSON_UNESCAPED_UNICODE)); }
    if ($removed && empty($permission['pode_excluir'])) { http_response_code(403); exit(json_encode(['ok' => false, 'message' => IdiomaService::t('manutencaolegalrequisitoslegais_checklist.erro.sem_permissao_excluir', ['pt' => 'Sem permissão para excluir perguntas.', 'en' => 'Not allowed to remove questions.', 'es' => 'Sin permiso para excluir preguntas.'])], JSON_UNESCAPED_UNICODE)); }
    foreach ($removed as $questionId) { $statement = $pdo->prepare('DELETE FROM legislacaoxpergunta WHERE CODLEGISLACAO = :law AND CODPERGUNTA = :question'); $statement->execute([':law' => $lawId, ':question' => $questionId]); }
    foreach ($added as $questionId) { $statement = $pdo->prepare('INSERT IGNORE INTO legislacaoxpergunta (CODLEGISLACAO, CODPERGUNTA) VALUES (:law, :question)'); $statement->execute([':law' => $lawId, ':question' => $questionId]); }
    header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok' => true], JSON_UNESCAPED_UNICODE); exit;
}
$lawStatement = $pdo->prepare('SELECT CODIGO FROM vw_legislacao_grid WHERE CODLEGISLACAO = :law'); $lawStatement->execute([':law' => $lawId]); $lawCode = (string)($lawStatement->fetchColumn() ?: $lawId);
$initial = $queryPage($pdo, $lawId, '', 1, $pageSize);
$selectedStatement = $pdo->prepare('SELECT CODPERGUNTA FROM legislacaoxpergunta WHERE CODLEGISLACAO = :law');
$selectedStatement->execute([':law' => $lawId]);
$initialSelected = array_map('intval', $selectedStatement->fetchAll(PDO::FETCH_COLUMN));
$canChecklistInclude = !empty($permission['pode_incluir']);
$canChecklistDelete = !empty($permission['pode_excluir']);
$canChecklistWrite = $canChecklistInclude || $canChecklistDelete;
echo '<script>window.checklistPermission=' . json_encode(['include' => $canChecklistInclude, 'delete' => $canChecklistDelete], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . ';</script>';
