search" data-search placeholder="<?= $tt('manutencaolegalrequisitoslegais_checklist.busca.placeholder', ['pt' => 'Buscar parte do código ou da pergunta', 'en' => 'Search part of the code or question', 'es' => 'Buscar parte del código o de la pregunta']) ?>" aria-label="<?= $tt('manutencaolegalrequisitoslegais_checklist.busca.dica', ['pt' => 'Buscar pergunta', 'en' => 'Search question', 'es' => 'Buscar pregunta']) ?>"><button type="submit" class="btn btn-sm btn-outline-secondary" title="<?= $tt('manutencaolegalrequisitoslegais_checklist.busca.pesquisar', ['pt' => 'Pesquisar', 'en' => 'Search', 'es' => 'Buscar']) ?>"><i class="bi bi-search"></i></button></form></div><div class="checklist-grid-wrap"><table class="table table-sm checklist-grid" id="checklistQuestionsGrid"><thead><tr><th style="width:42px"></th><th><?= $tt('manutencaolegalrequisitoslegais_checklist.coluna.pergunta', ['pt' => 'Pergunta', 'en' => 'Question', 'es' => 'Pregunta']) ?></th></tr></thead><tbody data-rows><?php foreach ($initial['items'] as $item): $questionId = (int)$item['CODPERGUNTA']; ?><tr data-question-id="<?= $questionId ?>" class="<?= !empty($item['associado']) ? 'associated' : '' ?>"><td><input type="checkbox" data-question-check <?= !empty($item['associado']) ? 'checked' : '' ?>></td><td class="question"><?= htmlspecialchars((string)$item['DSCPERGUNTA'], ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; ?></tbody></table></div><nav class="checklist-pagination"><button type="button" class="btn btn-sm btn-outline-secondary" data-prev title="<?= $tt('manutencaolegalrequisitoslegais_checklist.paginacao.anterior', ['pt' => 'Página anterior', 'en' => 'Previous page', 'es' => 'Página anterior']) ?>"><i class="bi bi-chevron-left"></i></button><span data-status><?= $initial['total'] ?> <?= $tt('manutencaolegalrequisitoslegais_checklist.paginacao.registros', ['pt' => 'registros · Página', 'en' => 'records · Page', 'es' => 'registros · Página']) ?> 1</span><button type="button" class="btn btn-sm btn-outline-secondary" data-next title="<?= $tt('manutencaolegalrequisitoslegais_checklist.paginacao.proxima', ['pt' => 'Próxima página', 'en' => 'Next page', 'es' => 'Página siguiente']) ?>"><i class="bi bi-chevron-right"></i></button></nav><div class="small text-danger" data-message></div><script>window.checklistInitial=<?= json_encode(['selected'=>$initialSelected,'total'=>$initial['total'],'pages'=>$initial['paginas']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;</script><script src="../assets/vendor/jquery/jquery-3.7.1.min.js"></script><?= IdiomaService::script(['comum'], [
