    'manutencaolegalrequisitoslegais_checklist.js.confirmar_mensagem' => ['pt' => 'Confirma a inclusão e/ou exclusão das perguntas selecionadas?', 'en' => 'Confirm adding and/or removing the selected questions?', 'es' => '¿Confirma la inclusión y/o exclusión de las preguntas seleccionadas?'],
    'manutencaolegalrequisitoslegais_checklist.js.erro_popup' => ['pt' => 'Não foi possível abrir o popup de confirmação.', 'en' => 'Could not open the confirmation popup.', 'es' => 'No fue posible abrir la ventana de confirmación.'],
    'manutencaolegalrequisitoslegais_checklist.js.erro_salvar' => ['pt' => 'Não foi possível salvar as associações.', 'en' => 'Could not save the associations.', 'es' => 'No fue posible guardar las asociaciones.'],
